export const BUG_STATUS_BUCKETS = ['Todo', 'In Progress', 'Ready to Test', 'Testing', 'Done']
export const BUG_GMS_MODULES = BUG_MODULES.filter((m) => /^gms/i.test(m.label))

export function normalizeBugLabel(label) {
  return String(label || '').trim().toLowerCase()
}

export function resolveBugModule(labels) {
  const matches = []
  for (const label of labels || []) {
    const hit = BUG_MODULE_BY_LABEL[normalizeBugLabel(label)]
    if (hit && !matches.some((m) => m.label.toLowerCase() === hit.label.toLowerCase())) {
      matches.push(hit)
    }
  }
  return matches
}

export function pickPrimaryBugModule(labels) {
  return resolveBugModule(labels)[0] || { label: '__unclassified__', name: 'Ch?a ph?n lo?i', count: 0 }
}

export function canonicalBugStatus(status) {
  const raw = String(status || '').trim()
  const key = raw.toLowerCase()
  if (!raw) return 'Kh?c'
  if (key === 'todo') return 'Todo'
  if (key === 'in progress') return 'In Progress'
  if (key === 'ready to test') return 'Ready to Test'
  if (key === 'testing') return 'Testing'
  if (key === 'done' || key === 'released') return 'Done'
  return raw
}

export function bugStatusOrder(status) {
  const index = BUG_STATUS_BUCKETS.indexOf(status)
  return index === -1 ? BUG_STATUS_BUCKETS.length : index
}
